    { type: "must", text: "Calculate AVL balance factors and identify which rotation case applies." },
    { type: "avoid", text: "Making TreeNode hardcoded to int  --  use generics (T extends Comparable<T>) for real implementations." },
    { type: "avoid", text: "Assuming BST is always balanced  --  sorted insertions produce O(n) height." },
    { type: "note", text: "In-order traversal of a valid BST always produces a sorted ascending sequence." },
  ]}
/>

